```javascript
import { 
  PlaneGeometry, 
  MeshBasicNodeMaterial, 
  Group, 
  TextureLoader,
  Color,
  Vector3
} from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const {
    textContent,
    colors,
    typography,
    scenePlacement,
    imageUrl,
  } = config;

  // Build the group that will be returned
  const group = new Group();
  group.position.set(
    scenePlacement.position[0],
    scenePlacement.position[1],
    scenePlacement.position[2]
  );
  group.rotation.set(
    scenePlacement.rotation[0],
    scenePlacement.rotation[1],
    scenePlacement.rotation[2]
  );
  group.scale.set(
    scenePlacement.scale[0],
    scenePlacement.scale[1],
    scenePlacement.scale[2]
  );

  // ---- Plane with image texture ----
  const planeGeometry = new PlaneGeometry(1.2, 0.4); // size suitable for a label
  const textureLoader = ctx.textureLoader || new TextureLoader();
  const texture = textureLoader.load(imageUrl || '/prism-mock/home/nodes/orb-decor.png');

  // Static composition: engineered gradient & subtle grain (simulated via texture)
  const planeMaterial = new MeshBasicNodeMaterial({
    map: texture,
    color: new Color(colors.paper || '#e8ecf2'), // fallback
    transparent: true,
  });

  const planeMesh = new Mesh(planeGeometry, planeMaterial);
  planeMesh.position.set(0, 0, 0); // centered within group
  group.add(planeMesh);

  // ---- Headline text using MSDF font atlas ----
  // Use typography.scale: headline -> 0.34 scene units, weight 400
  const headlineSize = typography?.scale?.headline || 0.34;
  const textColor = new Color(colors?.ink || '#16161d');
  const fontFamily = typography?.display?.split(' ')[0] || 'Lora';

  const textMesh = ctx.fontAtlas.createText(textContent[0]?.text || 'Pricing 1', {
    fontFamily: fontFamily,
    fontWeight: 400,
    fontSize: headlineSize,
    color: textColor,
    anchorX: 'center',
    anchorY: 'center',
  });

  // Position text on top of plane (slightly forward in z)
  textMesh.position.set(0, 0, 0.001);
  group.add(textMesh);

  // ---- Cleanup ----
  group.userData.cleanup = () => {
    planeGeometry.dispose();
    planeMaterial.dispose();
    texture.dispose();
    if (textMesh.material) textMesh.material.dispose();
    if (textMesh.geometry) textMesh.geometry.dispose();
    // Kills any GSAP timelines attached to this group
    const tl = group.userData._timeline;
    if (tl) tl.kill();
  };

  // Attach event handler container (none for this static element)
  group.userData.handlers = {};

  return group;
}
